import { useEffect, useMemo, useReducer } from 'react';
import { ThemeProvider } from 'styled-components';

import Button from './components/Button';
import Input from './components/Input';
import GlobalStyles from './global';
import theme from './theme';
import { CalculatorShell, Container, DisplayArea, Header, Keypad, SubTitle, Title } from './styles';

const operationLabels = {
  '+': '+',
  '-': '−',
  '*': '×',
  '/': '÷',
};

const operationAriaLabels = {
  '+': 'Somar',
  '-': 'Subtrair',
  '*': 'Multiplicar',
  '/': 'Dividir',
};

const initialState = {
  display: '0',
  storedValue: null,
  operator: null,
  waitingForOperand: false,
  error: '',
};

const formatNumber = (value) => {
  if (!Number.isFinite(value)) {
    return 'Erro';
  }

  if (Number.isInteger(value)) {
    return String(value);
  }

  return String(Number.parseFloat(value.toFixed(10)));
};

const calculate = (left, right, operator) => {
  switch (operator) {
    case '+':
      return { value: left + right };
    case '-':
      return { value: left - right };
    case '*':
      return { value: left * right };
    case '/':
      return right === 0 ? { error: 'Erro: divisão por zero' } : { value: left / right };
    default:
      return { value: right };
  }
};

const normalizeCurrentDisplay = (display) => {
  if (display === '-0') {
    return 0;
  }

  const value = Number(display);
  return Number.isNaN(value) ? null : value;
};

const clearState = {
  ...initialState,
};

const applyUnaryTransform = (state, transform) => {
  const currentValue = normalizeCurrentDisplay(state.display);

  if (currentValue === null) {
    return state;
  }

  return {
    ...state,
    display: formatNumber(transform(currentValue)),
    error: '',
    waitingForOperand: false,
  };
};

const reducer = (state, action) => {
  switch (action.type) {
    case 'CLEAR':
      return clearState;

    case 'DIGIT': {
      if (state.error) {
        return {
          ...initialState,
          display: action.digit,
        };
      }

      if (state.waitingForOperand) {
        return {
          ...state,
          display: action.digit,
          waitingForOperand: false,
        };
      }

      if (state.display === '0') {
        return {
          ...state,
          display: action.digit,
        };
      }

      if (state.display === '-0') {
        return {
          ...state,
          display: `-${action.digit}`,
        };
      }

      return {
        ...state,
        display: `${state.display}${action.digit}`,
      };
    }

    case 'DECIMAL': {
      if (state.error) {
        return {
          ...initialState,
          display: '0.',
        };
      }

      if (state.waitingForOperand) {
        return {
          ...state,
          display: '0.',
          waitingForOperand: false,
        };
      }

      if (state.display.includes('.')) {
        return state;
      }

      return {
        ...state,
        display: `${state.display}.`,
      };
    }

    case 'TOGGLE_SIGN':
      if (state.error) {
        return clearState;
      }

      return applyUnaryTransform(state, (value) => (value === 0 ? 0 : value * -1));

    case 'PERCENT':
      if (state.error) {
        return clearState;
      }

      return applyUnaryTransform(state, (value) => value / 100);

    case 'BACKSPACE': {
      if (state.error) {
        return clearState;
      }

      if (state.waitingForOperand) {
        return {
          ...state,
          display: '0',
          waitingForOperand: false,
        };
      }

      if (state.display.length <= 1 || (state.display.length === 2 && state.display.startsWith('-'))) {
        return {
          ...state,
          display: '0',
        };
      }

      return {
        ...state,
        display: state.display.slice(0, -1),
      };
    }

    case 'OPERATOR': {
      if (state.error) {
        return state;
      }

      const currentValue = normalizeCurrentDisplay(state.display);

      if (currentValue === null) {
        return state;
      }

      if (state.storedValue === null) {
        return {
          ...state,
          storedValue: formatNumber(currentValue),
          operator: action.operator,
          waitingForOperand: true,
        };
      }

      if (state.operator && !state.waitingForOperand) {
        const { value, error } = calculate(Number(state.storedValue), currentValue, state.operator);

        if (error) {
          return {
            ...clearState,
            display: error,
            error,
            waitingForOperand: true,
          };
        }

        const formattedValue = formatNumber(value);

        return {
          ...state,
          display: formattedValue,
          storedValue: formattedValue,
          operator: action.operator,
          waitingForOperand: true,
        };
      }

      return {
        ...state,
        operator: action.operator,
        waitingForOperand: true,
      };
    }

    case 'EQUALS': {
      if (state.error || state.storedValue === null || !state.operator || state.waitingForOperand) {
        return state;
      }

      const currentValue = normalizeCurrentDisplay(state.display);

      if (currentValue === null) {
        return state;
      }

      const { value, error } = calculate(Number(state.storedValue), currentValue, state.operator);

      if (error) {
        return {
          ...clearState,
          display: error,
          error,
          waitingForOperand: true,
        };
      }

      const formattedValue = formatNumber(value);

      return {
        ...state,
        display: formattedValue,
        storedValue: null,
        operator: null,
        waitingForOperand: false,
      };
    }

    default:
      return state;
  }
};

const App = () => {
  const [state, dispatch] = useReducer(reducer, initialState);

  const clearAll = () => dispatch({ type: 'CLEAR' });
  const inputDigit = (digit) => dispatch({ type: 'DIGIT', digit });
  const inputDecimal = () => dispatch({ type: 'DECIMAL' });
  const toggleSign = () => dispatch({ type: 'TOGGLE_SIGN' });
  const handlePercent = () => dispatch({ type: 'PERCENT' });
  const handleBackspace = () => dispatch({ type: 'BACKSPACE' });
  const handleOperator = (operator) => dispatch({ type: 'OPERATOR', operator });
  const handleEquals = () => dispatch({ type: 'EQUALS' });

  useEffect(() => {
    const handleKeyDown = (event) => {
      const { key, code, ctrlKey, metaKey, altKey } = event;

      if (ctrlKey || metaKey || altKey) {
        return;
      }

      const isNumericKey = key >= '0' && key <= '9';
      const isNumpadNumeric = code?.startsWith('Numpad') && key.length === 1 && key >= '0' && key <= '9';

      if (isNumericKey || isNumpadNumeric) {
        event.preventDefault();
        inputDigit(key);
        return;
      }

      if (key === '.' || key === ',') {
        event.preventDefault();
        inputDecimal();
        return;
      }

      if (key === 'Enter' || key === '=') {
        event.preventDefault();
        handleEquals();
        return;
      }

      if (key === 'Backspace') {
        event.preventDefault();
        handleBackspace();
        return;
      }

      if (key === 'Escape') {
        event.preventDefault();
        clearAll();
        return;
      }

      if (key === '+' || key === '-' || key === '*' || key === '/') {
        event.preventDefault();
        handleOperator(key);
        return;
      }

      if (key === '%') {
        event.preventDefault();
        handlePercent();
        return;
      }
    };

    window.addEventListener('keydown', handleKeyDown);

    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const expression = useMemo(() => {
    if (state.error) {
      return 'Operação interrompida';
    }

    if (state.storedValue === null || !state.operator) {
      return 'Pronta para cálculo';
    }

    const pendingValue = state.waitingForOperand ? '' : ` ${state.display}`;
    return `${state.storedValue} ${operationLabels[state.operator] ?? state.operator}${pendingValue}`;
  }, [state.display, state.error, state.operator, state.storedValue, state.waitingForOperand]);

  return (
    <ThemeProvider theme={theme}>
      <GlobalStyles />
      <Container>
        <CalculatorShell aria-label="Calculadora retro">
          <Header>
            <div>
              <Title>Calculadora</Title>
              <SubTitle>Painel de bancada analógico</SubTitle>
            </div>
          </Header>
          <DisplayArea>
            <Input error={state.error} expression={expression} value={state.display} />
          </DisplayArea>
          <Keypad>
            <Button ariaLabel="Limpar tudo" label="C" onClick={clearAll} title="Limpar" variant="danger" area="clear" />
            <Button ariaLabel="Trocar sinal" label="±" onClick={toggleSign} title="Trocar sinal" variant="accent" area="sign" />
            <Button ariaLabel="Porcentagem" label="%" onClick={handlePercent} title="Porcentagem" variant="accent" area="percent" />
            <Button ariaLabel={operationAriaLabels['/']} label="÷" onClick={() => handleOperator('/')} title="Dividir" variant="operator" area="divide" />

            <Button ariaLabel="Número 7" label="7" onClick={() => inputDigit('7')} variant="digit" area="seven" />
            <Button ariaLabel="Número 8" label="8" onClick={() => inputDigit('8')} variant="digit" area="eight" />
            <Button ariaLabel="Número 9" label="9" onClick={() => inputDigit('9')} variant="digit" area="nine" />
            <Button ariaLabel={operationAriaLabels['*']} label="×" onClick={() => handleOperator('*')} title="Multiplicar" variant="operator" area="multiply" />

            <Button ariaLabel="Número 4" label="4" onClick={() => inputDigit('4')} variant="digit" area="four" />
            <Button ariaLabel="Número 5" label="5" onClick={() => inputDigit('5')} variant="digit" area="five" />
            <Button ariaLabel="Número 6" label="6" onClick={() => inputDigit('6')} variant="digit" area="six" />
            <Button ariaLabel={operationAriaLabels['-']} label="−" onClick={() => handleOperator('-')} title="Subtrair" variant="operator" area="minus" />

            <Button ariaLabel="Número 1" label="1" onClick={() => inputDigit('1')} variant="digit" area="one" />
            <Button ariaLabel="Número 2" label="2" onClick={() => inputDigit('2')} variant="digit" area="two" />
            <Button ariaLabel="Número 3" label="3" onClick={() => inputDigit('3')} variant="digit" area="three" />
            <Button ariaLabel={operationAriaLabels['+']} label="+" onClick={() => handleOperator('+')} title="Somar" variant="operator" area="plus" />

            <Button ariaLabel="Número 0" label="0" onClick={() => inputDigit('0')} title="Zero" variant="digit" wide area="zero" />
            <Button ariaLabel="Ponto decimal" label="." onClick={inputDecimal} title="Decimal" variant="digit" area="decimal" />
            <Button ariaLabel="Resultado" label="=" onClick={handleEquals} title="Igual" variant="accent" area="equal" />
          </Keypad>
        </CalculatorShell>
      </Container>
    </ThemeProvider>
  );
};

export default App;
