import styled, { css } from 'styled-components';

const variants = {
  digit: css`
    color: ${({ theme }) => theme.colors.digitText};
    background: linear-gradient(180deg, ${({ theme }) => theme.colors.digitTop}, ${({ theme }) => theme.colors.digitBottom});
  `,
  operator: css`
    color: ${({ theme }) => theme.colors.operatorText};
    background: linear-gradient(180deg, ${({ theme }) => theme.colors.operatorTop}, ${({ theme }) => theme.colors.operatorBottom});
  `,
  accent: css`
    color: ${({ theme }) => theme.colors.accentText};
    background: linear-gradient(180deg, ${({ theme }) => theme.colors.accentTop}, ${({ theme }) => theme.colors.accentBottom});
  `,
  danger: css`
    color: ${({ theme }) => theme.colors.dangerText};
    background: linear-gradient(180deg, ${({ theme }) => theme.colors.dangerTop}, ${({ theme }) => theme.colors.dangerBottom});
  `,
};

export const ButtonContainer = styled.button`
  grid-area: ${({ $area }) => $area};
  min-width: 0;
  min-height: 62px;
  padding: 14px 12px;
  border: 0;
  border-radius: 18px;
  cursor: pointer;
  font-size: ${({ $variant }) => ($variant === 'operator' || $variant === 'accent' ? '1.2rem' : '1.12rem')};
  font-weight: 700;
  letter-spacing: 0.02em;
  user-select: none;
  box-shadow:
    0 6px 0 rgba(0, 0, 0, 0.32),
    0 14px 18px rgba(0, 0, 0, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.26);
  transition:
    transform 120ms ease,
    box-shadow 120ms ease,
    filter 120ms ease,
    translate 120ms ease;
  ${({ $variant = 'digit' }) => variants[$variant]}
  ${({ $wide }) =>
    $wide &&
    css`
      grid-column: span 2;
    `}

  &:hover {
    filter: saturate(1.05) brightness(1.03);
    transform: translateY(-1px);
  }

  &:active {
    transform: translateY(3px);
    box-shadow:
      0 3px 0 rgba(0, 0, 0, 0.32),
      0 8px 10px rgba(0, 0, 0, 0.12),
      inset 0 2px 4px rgba(0, 0, 0, 0.08);
  }

  &:focus-visible {
    outline: 3px solid ${({ theme }) => theme.colors.focus};
    outline-offset: 2px;
  }
`;
