import { Display, ErrorMessage, Expression, InputContainer } from './styles';

const Input = ({ error, expression, value }) => {
  return (
    <InputContainer>
      <Expression>{expression || 'Pronta para calcular'}</Expression>
      <Display
        aria-label="Resultado da calculadora"
        readOnly
        spellCheck="false"
        value={value}
      />
      {error ? <ErrorMessage role="status">{error}</ErrorMessage> : null}
    </InputContainer>
  );
};

export default Input;
